//! The quickstart: data typed by its schema, decoding, encoding and errors.
//! The same steps as typescript/examples/quickstart, on the same files.
//! Run: cargo run -p haus-example-quickstart

/// The types of thread.schema.haus, generated by build.rs.
mod thread {
    haus::include_schema!("thread");
}

use thread::Comment;

const THREAD: &str = include_str!("../../../../examples/thread.haus");
const REPLY: &str =
    r#"Comment { author: "me", at: Instant("2026-11-16T09:00:00Z"), text: "+1", likes: 0, replies: [] }"#;

fn likes(c: &Comment) -> i128 {
    c.likes.to_i128().unwrap_or_default() + c.replies.iter().map(likes).sum::<i128>()
}

fn depth(c: &Comment) -> usize {
    1 + c.replies.iter().map(depth).max().unwrap_or(0)
}

fn main() -> Result<(), haus::Error> {
    // 1. The thread, as typed data: Root is Comment, a struct; replies is a Vec<Comment>.
    let thread: thread::Root = haus::from_str(THREAD)?;
    println!("thread by {}: {} levels, {} likes", thread.author, depth(&thread), likes(&thread));

    // 2. Decode haus text with the schema, change it, encode it back.
    let reply: Comment = haus::from_str(REPLY)?;
    let liked = Comment { likes: (reply.likes.to_i128().unwrap_or_default() + 1).into(), ..reply };
    println!("{}", haus::to_string(&liked)?);

    // 3. A value that doesn't match the schema is an error that says where.
    if let Err(error) = haus::from_str::<Comment>(&REPLY.replace("likes: 0", r#"likes: "lots""#)) {
        println!("error: {error}");
    }
    Ok(())
}
